const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let me=null, currentPage="dashboard", renderPageRequestId=0, cache={courses:[],trainees:[],trainers:[],sessions:[],applications:[],batches:[],library:[]};
let dashboardSnapshot=null,dashboardSnapshotAt=0;
let permissionMatrix={}, masterUnlocked=false;
const pages={
 "ai-jobs":["التوليد المحلي والنتائج","طلباتك ونتائج جهاز التوليد"],
 "learning-path":["مساري الذكي","تعلّم يتكيف مع تقدمك"],"learning-lab":["مركز التعلم التكيفي","المهارات والسياسات والتقييم"],
 "ai-assistant":["المساعد الذكي","تعلم ودرّب وحلّل"],"ai-knowledge":["مكتبة المعرفة والتحليل الذكي","رفع الملفات والبحث والتحليل بالمصادر"],"ai-settings":["إعدادات الذكاء الاصطناعي","المحتوى والاستخدام"],
 "sheet-exams":["الأرشيف","ملفات الدورات والتقارير"],"sheet-evaluations":["قواعد البيانات","نتائج التقييمات الخارجية وتحليلها"],"course-gallery":["معرض الدورات المنفذة","صور وأرشيف الدورات"],"learning-progress":["سجل الإنجاز","النتائج والتقدم"],
 dashboard:["الرئيسية","ملخص التدريب"],reports:["تقارير وإحصائيات","لوحة مستقلة لكل تقرير"],"report-platform":["تقارير المنصة","المؤشرات العامة للمنصة"],"report-courses":["تقارير الدورات","تفاصيل التسجيل والتوزيع"],"report-trainers":["تقارير المحاضرين","مؤشرات نشاط المحاضرين"],courses:["الدورات التدريبية","إدارة الدورات"],trainees:["المتدربون","إدارة ملفات المتدربين"],
 trainers:["بيانات المحاضرين","إدارة ملفات المحاضرين"],sessions:["البث المباشر","جدولة الجلسات والبث المباشر"],attendance:["الحضور اليومي","متابعة الحضور"],applications:["طلبات الترشح","مراجعة طلبات الالتحاق بالدورات"],programs:["البرامج التدريبية","إدارة البرامج التدريبية وتجميع الدورات"],payments:["الدفعات التدريبية","متابعة الدفعات والمجموعات التدريبية"],library:["المكتبة","المواد والملفات التدريبية"],"my-programs":["برامجي","البرامج والدورات المرتبطة بحسابك"],tasks:["المهام","إدارة مهام المتدربين ومتابعة الإنجاز"],assignments:["الواجبات","استلام الواجبات ومراجعة التسليمات"],tests:["الاختبارات","الاختبارات والتقييمات التدريبية"],"evaluation-templates":["قوالب التقييم","إنشاء وإدارة نماذج التقييم"],"trainee-evaluation":["تقييم المتدربين","متابعة تقييمات المتدربين"],"trainer-evaluation":["تقييم المحاضرين","مراجعة تقييمات المحاضرين"],"program-evaluation":["تقييم البرنامج التدريبي","تحليل آراء المتدربين حول البرامج"],"trainee-rating":["تقييم متدرب","سجل تقييمات كل متدرب"],certificates:["الشهادات","الشهادات وسجل الإنجاز"],notifications:["الإشعارات","آخر التنبيهات الخاصة بحسابك"],contact:["اتصل بنا","وحدة التطوير والذكاء الاصطناعي — الإدارة المركزية للتدريب"],settings:["إعدادات المدير","تغيير كلمة المرور وإدارة صلاحيات الحسابات"]
};
async function api(url,opts={}){const res=await fetch("/api"+url,{credentials:"same-origin",headers:{"Content-Type":"application/json",...(opts.headers||{})},...opts});let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.error||data.message||"حدث خطأ");return data}
async function dashboardData(force=false){if(!force&&dashboardSnapshot&&Date.now()-dashboardSnapshotAt<60000)return dashboardSnapshot;const data=await api("/dashboard");dashboardSnapshot=data;dashboardSnapshotAt=Date.now();return data}
function esc(s=""){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function showMessage(text){const el=$("#message");el.textContent=text;el.hidden=false;setTimeout(()=>el.hidden=true,5000)}

function moduleForPage(page){
 if(["reports","report-platform","report-courses","report-trainers","dashboard"].includes(page))return "reports";
 if(["courses","programs","payments","my-programs"].includes(page))return "courses"; if(["trainees","trainers"].includes(page))return "people";
 if(page==="attendance")return "attendance"; if(page==="sessions")return "sessions"; if(["tasks","assignments","tests"].includes(page))return "activities";
 if(["evaluation-templates","trainee-evaluation","trainer-evaluation","program-evaluation","trainee-rating"].includes(page))return "evaluations";
 if(["library","training-plan"].includes(page))return "library"; if(["sheet-exams","sheet-evaluations"].includes(page))return "archive"; if(page==="course-gallery")return "gallery";
 if(page.startsWith("ai-")||["learning-path","learning-lab"].includes(page))return "ai"; if(page==="notifications")return "notifications"; if(page==="applications")return "applications"; if(page==="certificates")return "certificates"; if(page==="settings")return "settings"; return null;
}
function canAccessPage(page){
 if(!me)return false;
 const mk=moduleForPage(page); if(mk && permissionMatrix[`${mk}:${me.role}`]===false && !(me.role==="admin"&&masterUnlocked)) return false;
 if(me.role==="admin")return true;
 const commonAI=["ai-jobs","learning-path","ai-assistant"];
 if(commonAI.includes(page))return true;
 if(me.role==="trainer")return ["dashboard","courses","trainees","sessions","attendance","library","tasks","assignments","tests","notifications","programs","payments","learning-progress","sheet-exams","sheet-evaluations","course-gallery","learning-lab"].includes(page);
 if(me.role==="trainee")return ["dashboard","courses","sessions","library","training-plan","tasks","assignments","tests","attendance","notifications","programs","payments","learning-progress"].includes(page);
 return false;
}
function navItems(){
 const groups=[
  {id:"home",label:"الرئيسية",items:[["dashboard","الرئيسية"]]},
  {id:"reports",label:"تقارير وإحصائيات",items:[["reports","مركز التقارير"],["report-platform","تقارير المنصة"],["report-courses","تقارير الدورات"],["report-trainers","تقارير المحاضرين"]]},
  {id:"content",label:"إدارة المحتوى التدريبي",items:[["courses","الدورات التدريبية"],["programs","البرامج التدريبية"],["payments","الدفعات التدريبية"],["attendance","الحضور اليومي"],["sessions","البث المباشر"]]},
  {id:"trainee-tools",label:"أنشطة المتدربين",items:[["tasks","المهام"],["assignments","الواجبات"],["tests","الاختبارات"],["evaluation-templates","قوالب التقييم"],["trainee-evaluation","تقييم المتدربين"],["trainer-evaluation","تقييم المحاضرين"],["program-evaluation","تقييم البرنامج التدريبي"],["trainee-rating","تقييم متدرب"]]},
  {id:"people",label:"إدارة الأشخاص",items:[["trainees","المتدربون"],["trainers","المحاضرون"]]},
  {id:"applications",label:"طلبات الترشح",items:[["applications","طلبات الترشح"]]},
  {id:"library",label:"المكتبة",items:[["library","المكتبة التدريبية"],["training-plan","الخطة التدريبية"]]},
  {id:"learning-results",label:"النتائج والإنجاز",items:[["learning-progress","سجل الإنجاز والنتائج"],["sheet-exams","الأرشيف"],["sheet-evaluations","قواعد البيانات"],["course-gallery","معرض الدورات المنفذة"]]},
  {id:"ai-tools",label:"الذكاء الاصطناعي",items:[["ai-knowledge","مكتبة المعرفة والتحليل الذكي"],["ai-jobs","التوليد المحلي والنتائج"],["learning-path","مساري الذكي"],["learning-lab","مركز التعلم التكيفي"],["ai-assistant","مساعد التعلم والتدريب"],["ai-settings","إعدادات ومراجع المساعد"]]},
  {id:"platform-chat",label:"التواصل والإشعارات",items:[["notifications","الإشعارات والشات"]]},
  {id:"admin-settings",label:"إعدادات المدير",items:[["settings","كلمة المرور والصلاحيات"]]}
 ];
 const allowed=k=>canAccessPage(k);
 const currentGroup=groups.find(g=>g.items.some(([k])=>k===currentPage))?.id||"home";
 const expanded=window.__navExpanded||currentGroup; window.__navExpanded=expanded;
 const iconMap={"learning-path":"✧","learning-lab":"▥","ai-assistant":"✦","ai-settings":"⚙","ai-knowledge":"▤",dashboard:"⌂",reports:"▥","report-platform":"▦","report-courses":"▤","report-trainers":"♙",courses:"▣",programs:"▱",payments:"▦",attendance:"◷",sessions:"◉",tasks:"☑",assignments:"▤",tests:"ⓘ","evaluation-templates":"▧","trainee-evaluation":"☆","trainer-evaluation":"♙","program-evaluation":"☷","trainee-rating":"☆",trainees:"♧",trainers:"♙",applications:"▣",library:"▤","training-plan":"▤",settings:"⚙"};
 const html=groups.map(g=>{const items=g.items.filter(([k])=>allowed(k));if(!items.length)return "";if(g.id==="home")return `<button class="nav-btn ${currentPage==="dashboard"?"active":""}" data-page="dashboard">${g.label}</button>`;return `<button class="nav-group-btn ${g.id===currentGroup?"group-current":""}" data-toggle-group="${g.id}" aria-expanded="${expanded===g.id}"><span class="nav-group-label"><span class="nav-item-icon" aria-hidden="true">${({"ai-tools":"✦",reports:"▥",content:"▣","trainee-tools":"☑",people:"♙",applications:"▤",library:"▧","admin-settings":"⚙"})[g.id]||"•"}</span>${g.label}</span><span class="nav-chevron">${expanded===g.id?"⌄":"⌃"}</span></button>${expanded===g.id?`<div class="nav-submenu">${items.map(([k,label])=>`<button class="nav-btn nav-sub-btn ${currentPage===k?"active":""}" data-page="${k}"><span class="nav-item-icon" aria-hidden="true">${iconMap[k]||"•"}</span><span>${label}</span></button>`).join("")}</div>`:""}`}).join("");
 $("#nav").innerHTML=html;
}
function showAuth(setup){$("#appView").hidden=true;$("#authView").hidden=false;$("#setupForm").hidden=!setup;$("#loginForm").hidden=setup;$("#authTitle").textContent=setup?"إعداد المنصة لأول مرة":"الإدارة المركزية للتدريب";$("#authDescription").textContent=setup?"أنشئ حساب المدير. احفظ بيانات الدخول في مكان آمن.":"سجّل الدخول باستخدام حسابك.";$("#authError").textContent=""}
async function init(){try{const status=await api("/setup-status");if(status.needsSetup){showAuth(true);$("#setupKeyLabel").hidden=!status.setupKeyRequired;return}try{const data=await api("/me");me=data.user;showApp()}catch{showAuth(false)}}catch(e){showAuth(false);$("#authError").textContent="تعذر الاتصال بالخادم. تأكد أن npm start يعمل."}}
$("#setupForm").addEventListener("submit",async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));try{const data=await api("/setup",{method:"POST",body:JSON.stringify(body)});me=data.user;showApp()}catch(err){$("#authError").textContent=err.message}});
$("#loginForm").addEventListener("submit",async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));try{const data=await api("/login",{method:"POST",body:JSON.stringify(body)});me=data.user;showApp()}catch(err){$("#authError").textContent=err.message}});
$("#logoutBtn").addEventListener("click",async()=>{try{await api("/logout",{method:"POST"})}finally{me=null;showAuth(false)}});
async function showApp(){
 $("#authView").hidden=true;$("#appView").hidden=false;$("#userDisplay").textContent=me.display_name;$("#userRole").textContent={admin:"مدير المنصة",trainer:"مدرب",trainee:"متدرب"}[me.role];
 const isAdmin=me.role==="admin"; $("#encryptionControlBtn").hidden=!isAdmin; $("#permissionControlBtn").hidden=!isAdmin; $("#encryptionControlBtn").style.display=isAdmin?"inline-flex":"none"; $("#permissionControlBtn").style.display=isAdmin?"inline-flex":"none";
 try{const d=await api("/platform-permissions");permissionMatrix={};(d.permissions||[]).forEach(x=>permissionMatrix[`${x.module_key}:${x.role}`]=!!x.enabled);masterUnlocked=!!d.masterUnlocked}catch{}
 if(me.role==="admin")await refreshEncryptionButton(); navItems();renderPage("dashboard")
}
async function loadMyAttendance(){const target=$("#myAttendanceResult");if(!target)return;target.innerHTML="<p class=muted>جارٍ تحميل سجل الحضور...</p>";try{const rows=await api("/my-attendance");target.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>الدورة</th><th>التاريخ</th><th>الحالة</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.course_title)}</td><td>${esc(r.date)}</td><td><span class="status-pill">${esc(r.status)}</span></td></tr>`).join("")}</tbody></table></div>`:`<div class="empty">لا توجد سجلات حضور مرتبطة بحسابك حتى الآن.</div>`}catch(e){target.innerHTML=`<p class="error">${esc(e.message)}</p>`}}
document.addEventListener("submit",async e=>{if(e.target.id==="adminPasswordForm"){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const err=$("#passwordError");if(f.newPassword!==f.confirmPassword){err.textContent="كلمتا المرور غير متطابقتين.";return}try{await api("/admin/password",{method:"POST",body:JSON.stringify({currentPassword:f.currentPassword,newPassword:f.newPassword})});e.target.reset();showMessage("تم تغيير كلمة المرور بنجاح.")}catch(x){err.textContent=x.message}}});
document.addEventListener("input",e=>{if(e.target.id==="traineeSearch"||e.target.id==="trainerSearch"){const q=e.target.value.trim().toLowerCase();const table=e.target.id==="traineeSearch"?"#traineesTable":"#trainersTable";document.querySelectorAll(`${table} tbody tr`).forEach(r=>{r.hidden=!r.dataset.search.includes(q)});}});
// Dedicated capture handler for the Facebook course gallery.
// This route historically failed to open because the large delegated navigation handler
// could be bypassed/interrupted by other learning workspace click handlers.
document.addEventListener("click",e=>{
 const gallery=e.target.closest('[data-page="course-gallery"]');
 if(!gallery)return;
 e.preventDefault();
 e.stopImmediatePropagation();
 renderPage("course-gallery");
},true);
document.addEventListener("click",e=>{const group=e.target.closest("[data-toggle-group]");if(group){window.__navExpanded=window.__navExpanded===group.dataset.toggleGroup?"":group.dataset.toggleGroup;navItems();return}const b=e.target.closest("[data-page]");if(b){renderPage(b.dataset.page)}const open=e.target.closest("[data-open]");if(open){if(open.dataset.open==="batch")openBatchForm();else if(open.dataset.open==="resource")openResourceForm();else if(open.dataset.open==="training-plan")document.querySelector("#planLinkForm input[name=title]")?.focus();else openForm(open.dataset.open)}if(e.target.closest("[data-add-batch]"))openBatchForm();if(e.target.closest("[data-add-resource]"))openResourceForm();const db=e.target.closest("[data-delete-batch]");if(db)deleteBatch(Number(db.dataset.deleteBatch));const dr=e.target.closest("[data-delete-resource]");if(dr)deleteResource(Number(dr.dataset.deleteResource));const dp=e.target.closest("[data-delete-plan]");if(dp)deletePlan(Number(dp.dataset.deletePlan));const close=e.target.closest("[data-close]");if(close)$("#modalRoot").innerHTML="";const del=e.target.closest("[data-delete]");if(del)deleteItem(del.dataset.delete,Number(del.dataset.id));const edit=e.target.closest("[data-edit]");if(edit)openEdit(edit.dataset.edit,Number(edit.dataset.id));const enroll=e.target.closest("[data-enroll]");if(enroll)openEnroll(Number(enroll.dataset.enroll));const roster=e.target.closest("[data-show-trainees]");if(roster)showCourseTrainees(Number(roster.dataset.showTrainees));const courseLinks=e.target.closest("[data-course-links]");if(courseLinks)openCourseLinksForm(Number(courseLinks.dataset.courseLinks));const revealPassword=e.target.closest("[data-reveal-password]");if(revealPassword){const field=document.querySelector(`#course-password-${Number(revealPassword.dataset.revealPassword)}`);if(field){field.type=field.type==="password"?"text":"password";revealPassword.textContent=field.type==="text"?"إخفاء":"إظهار"}}const copyPassword=e.target.closest("[data-copy-password]");if(copyPassword){const field=document.querySelector(`#course-password-${Number(copyPassword.dataset.copyPassword)}`);if(field&&navigator.clipboard){navigator.clipboard.writeText(field.value).then(()=>showMessage("تم نسخ كلمة مرور الاختبار." )).catch(()=>showMessage("تعذر النسخ تلقائيًا؛ يمكنك إظهار كلمة المرور ونسخها يدويًا."))}else if(field){field.type="text";field.select();showMessage("حدّد كلمة المرور وانسخها يدويًا.")}}const appAction=e.target.closest("[data-application-action]");if(appAction)updateApplication(Number(appAction.dataset.id),appAction.dataset.applicationAction);const courseVisibility=e.target.closest("[data-course-visibility]");if(courseVisibility)toggleCourseVisibility(Number(courseVisibility.dataset.courseVisibility),courseVisibility.dataset.enabled==="1");const appDelete=e.target.closest("[data-application-delete]");if(appDelete)deleteApplication(Number(appDelete.dataset.applicationDelete));const actAdd=e.target.closest("[data-activity-add]");if(actAdd)openActivityForm(actAdd.dataset.activityAdd);const actDel=e.target.closest("[data-activity-delete]");if(actDel)deleteActivity(Number(actDel.dataset.activityDelete));if(e.target.closest("#loadMyAttendance"))loadMyAttendance();});
$("#menuBtn").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));
async function renderPage(page){
 if(!canAccessPage(page)){showMessage("ليس لديك صلاحية لفتح هذا القسم.");page="dashboard";}
 const requestId=++renderPageRequestId;
 currentPage=page;navItems();document.querySelectorAll(".portal-topnav [data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===page));$("#sidebar").classList.remove("open");
 const content=$("#pageContent");if(content)content.innerHTML=`<div class="page-instant-loader"><span></span><div><strong>${esc(pages[page]?.[0]||"جاري الفتح")}</strong><small>جاري تجهيز المحتوى…</small></div></div>`;
 const heading=$("#pageHeading");if(heading)heading.textContent=pages[page]?.[0]||page;const subheading=$("#subHeading");if(subheading)subheading.textContent=pages[page]?.[1]||"";
 try{
  if(page==='ai-jobs'){ const html=await AIQueue.page();if(requestId!==renderPageRequestId)return;$('#pageContent').innerHTML=html;AIQueue.bind();return; }
  if(['learning-path','learning-lab'].includes(page)){ const html=await AdaptiveWorkspace.page(page);if(requestId!==renderPageRequestId)return;$('#pageContent').innerHTML=html;AdaptiveWorkspace.bind();return; }
  if(page==='ai-knowledge'){ const html=await AIKnowledge.page();if(requestId!==renderPageRequestId)return;$('#pageContent').innerHTML=html;AIKnowledge.bind();return; }
  if(['ai-assistant','ai-settings'].includes(page)){ const html=await AIWorkspace.page(page);if(requestId!==renderPageRequestId)return;$('#pageContent').innerHTML=html;AIWorkspace.bind();return; }
  if(['tests','programs','payments','my-programs','sheet-exams','sheet-evaluations','learning-progress','course-gallery'].includes(page)){ const html=await learningPage(page);if(requestId!==renderPageRequestId)return;$('#pageContent').innerHTML=html;return; }
  if(page==='notifications') { $('#pageContent').innerHTML=platformNotificationsPage();return; }
  if(page==='contact') { $('#pageContent').innerHTML=contactPage();return; }
  const needTrainees=["dashboard","trainees","courses","attendance","applications","reports","report-platform","report-courses","report-trainers","tasks","assignments"].includes(page);
  const needTrainers=me.role==="admin"&&["dashboard","trainers","courses","reports","report-platform","report-courses","report-trainers"].includes(page);
  const needApplications=me.role==="admin"&&["dashboard","applications","reports","report-platform"].includes(page);
  const jobs=[["dashboard",dashboardData()]];
  if(needTrainees)jobs.push(["trainees",api("/trainees")]);
  if(needTrainers)jobs.push(["trainers",api("/trainers")]);
  if(needApplications)jobs.push(["applications",api("/applications")]);
  if(page==="payments")jobs.push(["batches",api("/batches")]);
  if(page==="library")jobs.push(["library",api("/library")]);
  const results=await Promise.all(jobs.map(async ([key,promise])=>[key,await promise]));
  if(requestId!==renderPageRequestId)return;
  const data=results.find(([key])=>key==="dashboard")?.[1]||{};
  for(const [key,value] of results){if(key==="trainees")cache.trainees=value||[];if(key==="trainers")cache.trainers=value||[];if(key==="applications")cache.applications=value||[];if(key==="batches")cache.batches=value||[];if(key==="library")cache.library=value||[]}
  cache.courses=data.courses||cache.courses||[];cache.sessions=data.sessions||cache.sessions||[];
  $("#pageContent").innerHTML=page==="dashboard"?dashboard(data):page==="reports"?reportsHub(data):page==="report-platform"?platformReport(data):page==="report-courses"?courseReport(data):page==="report-trainers"?trainerReport(data):page==="courses"?coursesPage():page==="trainees"?traineesPage():page==="trainers"?trainersPage():page==="sessions"?sessionsPage():page==="attendance"?attendancePage():page==="applications"?applicationsPage():page==="programs"?programsManagementPage():page==="payments"?batchesManagementPage():page==="library"?libraryManagementPage():page==="training-plan"?trainingPlanPage():page==="settings"?adminSettingsPage():await activityPage(page);
  if(page==="training-plan"){loadTrainingPlans();const pf=$("#planLinkForm");pf?.addEventListener("submit",async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(pf));try{await api("/training-plans",{method:"POST",body:JSON.stringify(b)});pf.reset();await loadTrainingPlans();showMessage("تم حفظ رابط الخطة التدريبية.")}catch(err){$("#planFormError").textContent=err.message}})}
 }catch(e){if(requestId===renderPageRequestId){showMessage(e.message);$('#pageContent').innerHTML=`<section class="panel"><h2>تعذر فتح ${esc(pages[page]?.[0]||'القسم')}</h2><p class="error">${esc(e.message)}</p><div class="actions"><button class="primary" data-page="${esc(page)}">إعادة المحاولة</button></div></section>`;}}
}
