  const setStage=(stage)=>{const order={transfer:0,drive:1,saved:2},active=order[stage]??0;stages.forEach((el,i)=>{el.classList.toggle('is-active',i===active);el.classList.toggle('is-done',i<active)});progress.dataset.stage=stage;};
