// V25: real course tasks, attachments, submissions and review.
async function workFile(file){if(!file||!file.size)return null;if(file.size>50*1024*1024)throw Error('الحد الأقصى للملف 50 ميجابايت.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({name:file.name,data:String(r.result).split(',')[1]});r.onerror=()=>reject(Error('تعذرت قراءة الملف.'));r.readAsDataURL(file)})}
function closeModal(){const root=$('#modalRoot');if(root)root.innerHTML=''}
function workModal(title,body){$('#modalRoot').innerHTML=`<div class="modal-shade"><div class="modal modal-wide"><div class="modal-head"><h2>${esc(title)}</h2><button class="outline" data-close>إغلاق ×</button></div>${body}</div></div>`}
function workDate(v){return v?new Date(v.replace(' ','T')+'Z').toLocaleString('ar-EG',{timeZone:'Africa/Cairo'}):'—'}
async function workPage(kind){
 const rows=await api('/work/activities/'+kind),student=me.role==='trainee',staff=['admin','trainer'].includes(me.role);
 const noun=kind==='assignments'?'واجب':'مهمة', plural=kind==='assignments'?'الواجبات':'المهام';
 window.workRows=rows;const sent=rows.filter(r=>r.my_submission).length;
 const submissions=rows.reduce((n,r)=>n+(Number(r.submission_count)||0),0);
 return `${head(pages[kind][0],student?`اعرض ${plural} المرتبطة بدوراتك، أرسل الحل، وتابع الدرجة والملاحظات.`:`أنشئ ${plural} لدوراتك وحدد المستهدفين وموعد التسليم ثم راجع الإجابات والدرجات.`)}
 <div class="activity-toolbar">${staff?`<button class="primary" data-activity-add="${kind}">＋ إضافة ${noun}</button>`:''}<button class="outline" data-page="${kind}">↻ تحديث</button><span class="activity-chip">${rows.length} ${noun}</span><span class="activity-chip">${student?`${sent} تم تسليمها`:`${submissions} تسليم`}</span></div>
 <div class="cards work-cards">${rows.map(r=>`<article class="card work-card"><div class="work-card-top"><span class="activity-chip">${esc(r.course_title||'عام')}</span><span class="status-pill">${student?(r.my_submission?(r.my_submission.reviewed_at?'تمت المراجعة':'تم التسليم — بانتظار المراجعة'):'لم يتم التسليم'):esc(r.status)}</span></div><h3>${esc(r.title)}</h3><p class="work-description">${esc(r.description||`افتح ${noun} للاطلاع على التفاصيل.`)}</p><p class="muted">موعد التسليم: ${esc(r.due_date||'غير محدد')}</p>${r.file_name?`<p>المرفق: ${esc(r.file_name)}</p>`:''}${student&&r.my_submission?.reviewed_at?`<p><strong>الدرجة:</strong> ${r.my_submission.grade??'—'} / 100</p><p>${esc(r.my_submission.feedback)}</p>`:''}<div class="actions"><button class="primary" data-work-open="${r.id}">${student?`فتح ${noun} والتسليم`:'عرض التسليمات والمراجعة'}</button>${staff?`<button class="outline danger" data-activity-delete="${r.id}">حذف</button>`:''}</div></article>`).join('')||`<section class="panel empty">لا توجد ${plural} متاحة لحسابك حالياً.</section>`}</div>`}

function openWorkForm(kind){if(!['admin','trainer'].includes(me.role))return;const noun=kind==='assignments'?'واجب':'مهمة';workModal('إنشاء '+noun+' للدورة',`<form id="workCreate" class="form-grid"><div class="field field-full"><label>عنوان ${noun}</label><input name="title" required maxlength="180" value="${kind==='tasks'?'ICDL Session 1 – Study Notes & Practice Worksheet':''}"></div><div class="field"><label>الدورة التدريبية</label><select name="course_id" required><option value="">اختر الدورة</option>${cache.courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></div><div class="field"><label>آخر يوم للتسليم بتوقيت القاهرة</label><input name="due_date" type="date"></div><div class="field"><label>الحالة</label><select name="status"><option>نشط</option><option>مسودة</option><option>قيد التنفيذ</option><option>مغلق</option></select></div><div class="field"><label>نوع الإجابة المطلوبة</label><select name="submission_type"><option>ملف أو نص</option><option>ملف مرفق</option><option>نص داخل المنصة</option></select></div><div class="field field-full"><label>التعليمات</label><textarea name="description" rows="4" required>اقرأ ملف المذاكرة، ثم أجب عن الأسئلة والتدريبات وأرسل إجابتك هنا للمراجعة.</textarea></div><div class="field field-full"><label>ملف ${noun} — حتى 50 ميجابايت</label><input name="attachment" type="file" accept=".doc,.docx,.xls,.xlsx,.ppt,.pptx,.pdf,.txt,.png,.jpg,.jpeg"><label class="choice-row"><input name="use_icdl" type="checkbox"> استخدام ملف ICDL Session 1 المرفق مع المشروع بدلاً من رفع ملف</label></div><div class="field field-full"><label>المستهدفون</label><p class="muted">اترك الاختيارات فارغة لإتاحتها لجميع المسجلين في الدورة، بما فيهم من يسجل لاحقاً.</p><div id="workTargets">اختر الدورة أولاً.</div></div><div class="field-full"><button class="primary">نشر وحفظ المهمة</button><p id="workError" class="error" role="alert"></p></div></form>`);const form=$('#workCreate');let loading=false;form.course_id.onchange=async()=>{loading=true;$('#workTargets').innerHTML='جارٍ تحميل المتدربين...';try{const rows=await api(`/courses/${form.course_id.value}/enrolled`);$('#workTargets').innerHTML=rows.map(t=>`<label class="choice-row"><input type="checkbox" name="trainee_ids" value="${t.id}">${esc(t.name)}</label>`).join('')||'لا يوجد مسجلون حالياً؛ ستتاح المهمة عند التسجيل.'}catch(e){$('#workTargets').textContent=e.message}finally{loading=false}};form.onsubmit=async e=>{e.preventDefault();if(loading)return;const button=form.querySelector('button');button.disabled=true;try{const fd=new FormData(form),body=Object.fromEntries(fd);body.trainee_ids=fd.getAll('trainee_ids').map(Number);body.use_icdl=fd.has('use_icdl');delete body.attachment;body.file=body.use_icdl?null:await workFile(form.attachment.files[0]);await api('/work/activities/'+kind,{method:'POST',body:JSON.stringify(body)});$('#modalRoot').innerHTML='';await renderPage(kind);showMessage('تم حفظ '+noun+' وإتاحته للمتدربين المستهدفين.')}catch(e){$('#workError').textContent=e.message}finally{button.disabled=false}}}
async function openWork(id){const a=window.workRows.find(r=>r.id===id);if(!a)return;try{const rows=await api(`/work/${id}/submissions`),student=me.role==='trainee';workModal(a.title,`<p class="muted">${esc(a.course_title)} · موعد التسليم: ${esc(a.due_date||'غير محدد')} · ${esc(a.status)}</p><p class="work-answer">${esc(a.description)}</p>${a.file_id?`<a class="primary work-download" href="/api/work/${id}/file/${a.file_id}">تنزيل ملف المهمة — ${esc(a.file_name||'مرفق')}</a>`:''}${student?`<form id="workSubmit" class="form-grid"><div class="field field-full"><label>إجابتك</label><textarea name="answer" rows="7" maxlength="20000" placeholder="اكتب إجاباتك مع أرقام الأسئلة"></textarea></div><div class="field field-full"><label>إرفاق ملف الحل — حتى 50 ميجابايت</label><input name="attachment" type="file" accept=".doc,.docx,.pdf,.xls,.xlsx,.ppt,.pptx,.txt,.png,.jpg,.jpeg"><small>${esc(a.submission_type||'ملف أو نص')}</small></div><div class="field-full"><button class="primary">إرسال الإجابة</button><p class="error" id="workError" role="alert"></p></div></form>`:''}<h3>${student?'سجل تسليماتي':'تسليمات المتدربين'} (${rows.length})</h3>${rows.map(s=>`<article class="work-submission"><strong>${esc(s.trainee_name)}</strong><p class="muted">التسليم #${s.id} · ${workDate(s.submitted_at)} · ${s.reviewed_at?'تمت المراجعة':'بانتظار المراجعة'}</p><p class="work-answer">${esc(s.answer||'إجابة في الملف المرفق')}</p>${s.file_id?`<a class="tiny" href="/api/work/${id}/file/${s.file_id}">ملف الحل: ${esc(s.file_name)}</a>`:''}${student?`<p>الدرجة: ${s.grade??'—'} / 100</p><p class="work-answer">${esc(s.feedback)}</p>`:`<form class="workReview form-grid" data-submission="${s.id}"><div class="field"><label>الدرجة من 100</label><input name="grade" type="number" min="0" max="100" step="0.01" value="${s.grade??''}"></div><div class="field field-full"><label>ملاحظات المراجعة</label><textarea name="feedback" maxlength="10000">${esc(s.feedback)}</textarea></div><button class="primary">حفظ المراجعة</button><p class="error" role="alert"></p></form>`}</article>`).join('')||'<p class="empty">لا توجد تسليمات حتى الآن.</p>'}`);$('#workSubmit')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,b=form.querySelector('button');b.disabled=true;try{await api(`/work/${id}/submit`,{method:'POST',body:JSON.stringify({answer:form.answer.value,file:await workFile(form.attachment.files[0])})});await renderPage(currentPage);await openWork(id);showMessage('تم تسجيل إجابتك وإرسالها للمراجعة.')}catch(e){$('#workError').textContent=e.message}finally{b.disabled=false}});$$('.workReview').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;try{await api(`/work/${id}/review/${form.dataset.submission}`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});await openWork(id);showMessage('تم حفظ المراجعة.')}catch(e){form.querySelector('.error').textContent=e.message}finally{b.disabled=false}})}catch(e){showMessage(e.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-work-open]');if(b)openWork(Number(b.dataset.workOpen))});

// V26 management editor. Identifiers remain unchanged so links and submissions survive edits.
async function openAdminRecord(type,id){if(me.role!=='admin')return;try{
 const item=await api(`/admin/edit/${type}/${id}`);if(type==='courses')cache.trainers=await api('/trainers');
 const specs={courses:[['title','اسم الدورة'],['display_number','رقم العرض أو كود الدورة (مثال 47)'],['description','الوصف','textarea'],['trainer_id','المحاضر','trainer'],['starts_on','البداية','date'],['ends_on','النهاية','date'],['capacity','العدد المستهدف — صفر يعني بدون حد','number'],['public_registration_enabled','إظهار الدورة في الخطة العامة','checkbox']],sessions:[['title','عنوان الجلسة'],['course_id','الدورة','course'],['starts_at','موعد البداية','datetime-local'],['duration','المدة بالدقائق','number'],['platform','المنصة'],['url','رابط الاجتماع','url']],batches:[['title','اسم الدفعة'],['course_id','الدورة','course'],['code','كود الدفعة'],['starts_on','البداية','date'],['ends_on','النهاية','date'],['notes','ملاحظات','textarea']],activities:[['title','عنوان النشاط'],['description','التعليمات','textarea'],['course_id','الدورة','course'],['due_date','التسليم','date'],['status','الحالة','status'],['external_url','الرابط الخارجي','url']],library:[['title','عنوان المرجع'],['kind','نوع المرجع'],['course_id','الدورة','course'],['description','الوصف','textarea']],'training-plans':[['title','اسم الخطة'],['url','الرابط','url'],['description','الوصف','textarea']],applications:[['applicant_name','اسم المتقدم'],['email','البريد','email'],['phone','الهاتف','tel'],['course_id','الدورة','course'],['admin_note','ملاحظات الإدارة','textarea']]};
 const task=type==='activities'&&['tasks','assignments'].includes(item.kind);
 const field=([name,label,kind='text'])=>{let control;const value=item[name]??'';
 if(kind==='textarea')control=`<textarea name="${name}" rows="4" maxlength="20000">${esc(value)}</textarea>`;
 else if(['course','trainer','status'].includes(kind)){const opts=kind==='course'?[['','بدون دورة'],...cache.courses.map(c=>[c.id,c.title])]:kind==='trainer'?[['','بدون محاضر'],...cache.trainers.map(t=>[t.id,t.name])]:['نشط','مسودة','قيد التنفيذ','مكتمل','مغلق'].map(s=>[s,s]);if(value&&!opts.some(o=>String(o[0])===String(value)))opts.push([value,value]);control=`<select name="${name}">${opts.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select>`}
 else control=`<input name="${name}" type="${kind}" ${kind==='checkbox'?(Number(value)===1?'checked':''):`value="${esc(value)}"`} ${name==='title'||name==='applicant_name'?'required':''} ${kind==='number'?'min="0" step="1"':''}>`;
 return `<div class="field ${kind==='textarea'?'field-full':''}"><label>${esc(label)}</label>${control}</div>`};
 workModal('تعديل السجل',`<form id="adminRecordForm" class="form-grid">${specs[type].map(field).join('')}${type==='courses'?'<p class="muted field-full">يمكن تغيير العدد المستهدف مثلاً من 17 إلى 47. عدد المسجلين الفعلي يُحسب من التسجيلات. رقم العرض يغيّر الشارة في الخطة العامة دون تغيير معرف الدورة.</p>':''}${task?`<div class="field"><label>نوع التسليم</label><select name="submission_type">${['ملف أو نص','ملف مرفق','نص داخل المنصة'].map(v=>`<option ${v===item.submission_type?'selected':''}>${v}</option>`).join('')}</select></div><div class="field field-full"><label>المتدربون المستهدفون — عدم الاختيار يعني جميع المسجلين</label><div id="editTaskTargets"></div></div><div class="field field-full"><label>استبدال ملف المهمة (اختياري)</label><input name="replacement" type="file" accept=".doc,.docx,.pdf,.xls,.xlsx,.ppt,.pptx,.txt,.png,.jpg,.jpeg"><label class="choice-row"><input name="use_icdl" type="checkbox"> استخدام ملف ICDL</label><label class="choice-row"><input name="remove_file" type="checkbox"> إزالة مرفق المهمة الحالي</label><small>التعديل يحتفظ بجميع محاولات المتدربين ومراجعاتهم السابقة.</small></div>`:''}<div class="modal-actions field-full"><button class="primary">حفظ التعديلات</button><button type="button" class="outline" data-close>إلغاء</button></div><p class="error field-full" id="adminRecordError" role="alert"></p></form>`);
 const form=$('#adminRecordForm');let targetLoading=false;
 async function targets(keep){targetLoading=true;try{const selected=keep?JSON.parse(item.trainee_ids||'[]'):[];const course=form.elements.course_id.value;const rows=course?await api(`/courses/${course}/enrolled`):[];$('#editTaskTargets').innerHTML=rows.map(t=>`<label class="choice-row"><input name="trainee_ids" type="checkbox" value="${t.id}" ${selected.includes(t.id)?'checked':''}>${esc(t.name)}</label>`).join('')||'لا يوجد مسجلون.'}finally{targetLoading=false}}
 if(task){await targets(true);form.elements.course_id.onchange=()=>targets(false).catch(e=>$('#adminRecordError').textContent=e.message)}
 form.onsubmit=async e=>{e.preventDefault();if(targetLoading)return;const b=form.querySelector('button');b.disabled=true;try{const fd=new FormData(form),body={};for(const [k,v]of fd)if(!(v instanceof File)&&k!=='trainee_ids')body[k]=v;if(type==='courses')body.public_registration_enabled=form.elements.public_registration_enabled.checked;if(task){body.trainee_ids=fd.getAll('trainee_ids').map(Number);body.use_icdl=fd.has('use_icdl');body.remove_file=fd.has('remove_file');body.file=await workFile(form.elements.replacement.files[0]);}await api(`/admin/edit/${type}/${id}`,{method:'PUT',body:JSON.stringify(body)});$('#modalRoot').innerHTML='';await renderPage(currentPage);showMessage('تم حفظ التعديلات.')}catch(e){$('#adminRecordError').textContent=e.message}finally{b.disabled=false}};
 }catch(e){showMessage(e.message)}}
async function mailCredentials(id,button){if(!confirm('إرسال اسم المستخدم وكلمة المرور إلى بريد المتدرب المسجل؟'))return;button.disabled=true;try{const r=await api(`/trainees/${id}/send-credentials`,{method:'POST',body:'{}'});await renderPage(currentPage);showMessage(r.message)}catch(e){showMessage(e.message)}finally{button.disabled=false}}
document.addEventListener('click',e=>{const edit=e.target.closest('[data-admin-record]');if(edit)openAdminRecord(edit.dataset.adminRecord,Number(edit.dataset.recordId));const mail=e.target.closest('[data-mail-credentials]');if(mail)mailCredentials(Number(mail.dataset.mailCredentials),mail);const check=e.target.closest('[data-google-check]');if(check){check.disabled=true;api('/admin/google-status').then(r=>{$('#googleConnectionResult').textContent=`الاتصال ناجح — المجلد: ${r.folder} — رسائل البريد المتبقية اليوم: ${r.remainingMailQuota}`}).catch(e=>$('#googleConnectionResult').textContent=e.message).finally(()=>check.disabled=false)}});
const originalAdminSettingsPage=adminSettingsPage;
adminSettingsPage=function(){return originalAdminSettingsPage()+`<section class="panel integration-panel"><h2>ربط البريد والملفات مع Google</h2><p>بعد نشر Apps Script وضبط متغيرات الاستضافة، اختبر الوصول إلى مجلد platform وصلاحية إرسال البريد.</p><button class="primary" data-google-check>اختبار اتصال Google</button><p id="googleConnectionResult" role="status"></p></section>`};
// A single touch-scrolling surface for dialogs; restore the previous focus after closing.
let dialogReturnFocus=null;
new MutationObserver(()=>{const shade=$('#modalRoot .modal-shade');document.body.classList.toggle('dialog-open',!!shade);if(shade&&!shade.dataset.accessible){dialogReturnFocus=document.activeElement;shade.dataset.accessible='1';const modal=shade.querySelector('.modal');modal?.setAttribute('role','dialog');modal?.setAttribute('aria-modal','true');const title=modal?.querySelector('h2');if(title){title.id='activeDialogTitle';modal.setAttribute('aria-labelledby',title.id)}shade.scrollTop=0;modal?.querySelector('input:not([type=hidden]),select,textarea,button')?.focus({preventScroll:true})}else if(!shade&&dialogReturnFocus){dialogReturnFocus.focus?.({preventScroll:true});dialogReturnFocus=null}}).observe($('#modalRoot'),{childList:true});
document.addEventListener('keydown',e=>{const modal=$('#modalRoot .modal');if(!modal)return;if(e.key==='Escape'){$('#modalRoot').innerHTML='';return}if(e.key==='Tab'){const controls=[...modal.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});


async function refreshEncryptionButton(){const b=$("#encryptionControlBtn");if(!b||me?.role!=="admin")return;try{const d=await api("/storage-encryption");b.textContent=d.encrypted?"DECRYPT":"ENCRYPT";b.dataset.encrypted=d.encrypted?"1":"0";b.title=d.encrypted?"فك تشفير بيانات الجداول":"إعادة تشفير بيانات الجداول"}catch{b.textContent="ENCRYPTION"}}
async function unlockMaster(){if(masterUnlocked)return true;const password=prompt("أدخل كلمة مرور التحكم الرئيسية:");if(!password)return false;try{await api("/master-control/unlock",{method:"POST",body:JSON.stringify({password})});masterUnlocked=true;return true}catch(e){showMessage(e.message);return false}}
$("#encryptionControlBtn")?.addEventListener("click",async()=>{if(!await unlockMaster())return;const b=$("#encryptionControlBtn"),currently=b.dataset.encrypted==="1",target=!currently,verb=target?"إعادة تشفير":"فك تشفير";if(!confirm(`${verb} بيانات جداول المنصة الآن؟ ستظل المنصة قابلة للاستخدام أثناء تغيير صيغة التخزين.`))return;b.disabled=true;try{const d=await api("/storage-encryption",{method:"POST",body:JSON.stringify({encrypted:target})});showMessage(d.message);await refreshEncryptionButton()}catch(e){showMessage(e.message)}finally{b.disabled=false}});
$("#permissionControlBtn")?.addEventListener("click",async()=>{if(!await unlockMaster())return;await openPermissionControl()});
async function openPermissionControl(){const d=await api("/platform-permissions"),roles=[['admin','المديرون الآخرون'],['trainer','المحاضرون'],['trainee','المتدربون']],map={};(d.permissions||[]).forEach(x=>map[`${x.module_key}:${x.role}`]=!!x.enabled);$("#modalRoot").innerHTML=`<div class="modal-shade"><div class="modal permission-master-modal"><div class="modal-head"><div><h2>PERMISSION · التحكم الرئيسي</h2><p class="muted">تشغيل أو إيقاف أقسام المنصة حسب نوع الحساب.</p></div><button class="outline" data-close>إغلاق ×</button></div><div class="permission-grid"><div class="permission-head">القسم</div>${roles.map(r=>`<div class="permission-head">${r[1]}</div>`).join('')}${(d.modules||[]).map(m=>`<strong>${esc(m.label)}</strong>${roles.map(r=>{const on=map[`${m.key}:${r[0]}`]!==false;return `<label class="permission-switch"><input type="checkbox" data-permission-module="${m.key}" data-permission-role="${r[0]}" ${on?'checked':''}><span>${on?'مفعّل':'موقوف'}</span></label>`}).join('')}`).join('')}</div><div class="master-security-note">التغيير يطبق على الواجهة وطلبات الخادم، وليس مجرد إخفاء للقائمة.</div></div></div>`;$("#modalRoot").querySelectorAll('[data-permission-module]').forEach(el=>el.addEventListener('change',async()=>{el.disabled=true;try{await api('/platform-permissions',{method:'PUT',body:JSON.stringify({module_key:el.dataset.permissionModule,role:el.dataset.permissionRole,enabled:el.checked})});el.nextElementSibling.textContent=el.checked?'مفعّل':'موقوف';permissionMatrix[`${el.dataset.permissionModule}:${el.dataset.permissionRole}`]=el.checked;navItems()}catch(e){el.checked=!el.checked;showMessage(e.message)}finally{el.disabled=false}}))}
document.addEventListener('submit',async e=>{if(e.target.id!=="contactMessageForm")return;e.preventDefault();const form=e.target,status=$("#contactSendStatus"),btn=form.querySelector('button[type=submit]');btn.disabled=true;status.textContent='جارٍ إرسال الرسالة...';try{const body=Object.fromEntries(new FormData(form));const d=await api('/contact-message',{method:'POST',body:JSON.stringify(body)});form.reset();status.textContent=d.message;status.className='success'}catch(err){let msg=err.message;if(me?.role==='admin'){try{await api('/platform-bridge-health')}catch(h){msg+=' | فحص الربط: '+h.message}}status.textContent=msg;status.className='error'}finally{btn.disabled=false}});


document.addEventListener("click",e=>{const report=e.target.closest("[data-trainee-report]");if(report)openTraineePerformanceReport(Number(report.dataset.traineeReport),report.dataset.courseId?Number(report.dataset.courseId):null);});
async function openTraineePerformanceReport(id,courseId=null){
 const root=$('#modalRoot');
 root.innerHTML=`<div class="modal-shade"><div class="modal modal-wide"><div class="modal-head"><div><h2>ملف أداء المتدرب</h2><p class="muted">${courseId?`تقرير الدورة رقم ${courseId} فقط`:"التقرير الشامل لجميع الدورات"} · جارٍ قراءة السجلات الفعلية.</p></div><button class="outline" data-close>إغلاق ×</button></div><div id="traineePerformanceBody"></div></div></div>`;
 try{
  const data=await api(`/trainees/${id}/performance-report${courseId?`?course_id=${courseId}`:""}`),t=data.trainee,body=$('#traineePerformanceBody');
  const dt=value=>{if(!value)return '—';const date=new Date(String(value).replace(' ','T'));return Number.isNaN(date.getTime())?esc(value):date.toLocaleString('ar-EG',{timeZone:'Africa/Cairo'})};
  const table=(headers,rows,empty='لا توجد سجلات محفوظة.')=>`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}">${empty}</td></tr>`}</tbody></table></div>`;
  const courses=data.courses.map(course=>`<section class="panel trainee-report-course">
   <h3>${esc(course.title)}</h3>
   <p class="muted">${esc(course.starts_on||'—')} إلى ${esc(course.ends_on||'—')} · البرامج: ${esc((course.programs||[]).map(p=>p.title).join('، ')||'—')}</p>
   <div class="meta">
    <span>تسليمات: ${course.summary.submissions}</span>
    <span>محاولات اختبارات: ${course.summary.test_attempts}</span>
    <span>فيديوهات بدأها: ${course.summary.videos_started}/${course.summary.video_count}</span>
    <span>متوسط الأداء: ${course.summary.average_grade===null?'—':course.summary.average_grade+'%'}</span>
    <span>حضور ${course.attendance_summary.present} · غياب ${course.attendance_summary.absent} · تأخير ${course.attendance_summary.late}</span>
   </div></section>`).join('');
  const work=data.courses.flatMap(c=>(c.work||[]).map(x=>({...x,course_title:c.title})));
  const tests=data.courses.flatMap(c=>(c.tests||[]).map(x=>({...x,course_title:c.title})));
  const attendance=data.courses.flatMap(c=>(c.attendance||[]).map(x=>({...x,course_title:c.title})));
  const videos=data.courses.flatMap(c=>(c.videos||[]).map(x=>({...x,course_title:c.title})));
  const workRows=work.map(x=>`<tr><td>${esc(x.course_title)}</td><td>${x.kind==='tasks'?'مهمة':'واجب'}</td><td>${esc(x.title)}</td><td>${dt(x.submitted_at)}</td><td>${x.grade===null?'لم ترصد':esc(x.grade)}</td><td>${esc(x.feedback||'—')}</td><td>${esc(x.file_name||x.answer||'—')}</td></tr>`).join('');
  const testRows=tests.map(x=>`<tr><td>${esc(x.course_title)}</td><td>${esc(x.title)}</td><td>#${x.attempt_id}</td><td>${dt(x.started_at)}</td><td>${dt(x.submitted_at)}</td><td>${x.score===null?'لم ترصد':esc(x.score)+' / '+esc(x.total_score)}</td><td>${esc(x.status||'—')}</td><td>${x.questions.length?`صحيح ${x.correct_count} · خطأ ${x.wrong_count}`:esc(x.feedback||x.file_name||'—')}</td></tr>`).join('');
  const attendanceRows=attendance.map(x=>`<tr><td>${esc(x.course_title)}</td><td>${esc(x.date)}</td><td>${esc(x.status)}</td></tr>`).join('');
  const videoSections=videos.map(video=>`<section class="panel">
   <h4>${esc(video.title)} <span class="muted">— ${esc(video.course_title)}</span></h4>
   <div class="meta"><span>المشاهدة: ${video.watched_percent}%</span><span>الوقت المشاهد: ${Math.round(video.watched_seconds/60)} دقيقة</span><span>آخر مشاهدة: ${dt(video.last_watched_at)}</span><span>الأسئلة: ${video.questions.length}</span><span>الدرجة: ${video.possible_points?`${video.awarded_points} / ${video.possible_points}`:'—'}</span></div>
   ${video.questions.length?video.questions.map((q,i)=>`<div class="trainee-video-question"><p><strong>س${i+1} (${Math.floor(q.at_seconds)} ثانية):</strong> ${esc(q.question)}</p><p>الدرجة: ${q.points_awarded} / ${q.points} · المحاولات: ${q.attempts_count} · الإجابات الصحيحة: ${q.correct_attempts}</p>
   ${q.attempts.map((a,j)=>`<p class="muted">محاولة ${j+1}: ${esc(a.answer_text||'—')} · ${a.is_correct?'صحيحة':'خاطئة'} · ${a.points_awarded} درجة · ${dt(a.attempted_at)}</p>`).join('')||'<p class="muted">لم تتم الإجابة عن السؤال.</p>'}</div>`).join(''):'<p class="muted">لا توجد أسئلة لهذا الفيديو.</p>'}
  </section>`).join('');
  const testDetails=tests.filter(x=>x.questions.length).map(x=>`<section class="panel"><h4>${esc(x.title)} — ${esc(x.course_title)} — المحاولة #${x.attempt_id}</h4>${x.questions.map((q,i)=>`<p><strong>س${i+1}:</strong> ${esc(q.question)}<br>إجابة المتدرب: ${esc(q.answer_text||'لم تتم الإجابة')} · الصحيحة: ${esc(q.correct_text||'—')} · ${q.correct?'صحيح':'غير صحيح'}</p>`).join('')}</section>`).join('');
  body.innerHTML=`<div id="traineeReportPrint">
   <header class="trainee-report-header"><h1>British Institute Tanta</h1><h2>تقرير أداء المتدرب</h2><p><strong>${esc(t.name)}</strong> · ${esc(t.phone||'—')} · ${esc(t.email||'—')} · ${esc(t.department||'—')}</p><p>تاريخ إنشاء التقرير: ${dt(data.generated_at)}</p></header>
   <h3>ملخص الأداء حسب الدورة</h3>${courses||'<p>لا توجد دورات مسجل بها المتدرب.</p>'}
   <h3>المهام والواجبات والتسليمات</h3>${table(['الدورة','النوع','النشاط','تاريخ التسليم','الدرجة','ملاحظات المدرب','الإجابة / الملف'],workRows)}
   <h3>الاختبارات والمحاولات</h3>${table(['الدورة','الاختبار','المحاولة','البدء','التسليم','الدرجة','الحالة','النتيجة'],testRows)}${testDetails?`<h4>تفاصيل إجابات الاختبارات</h4>${testDetails}`:''}
   <h3>الفيديوهات التعليمية وإجابات الأسئلة</h3>${videoSections||'<p>لا توجد فيديوهات مرتبطة بدورات هذا المتدرب.</p>'}
   <h3>الحضور والغياب والتأخير</h3>${table(['الدورة','التاريخ','الحالة'],attendanceRows)}
  </div><div class="modal-actions">${courseId?`<button class="outline" id="showAllTraineeCourses">عرض ملف الأداء الشامل لكل الدورات</button>`:`<button class="outline" id="showCurrentTraineeCourse" disabled>عرض جميع الدورات</button>`}<button class="primary" id="printTraineeReport">طباعة / حفظ PDF</button><button class="outline" data-close>إغلاق التقرير</button></div>`;
  $('#showAllTraineeCourses')?.addEventListener('click',()=>openTraineePerformanceReport(id));
  $('#printTraineeReport').onclick=()=>{
   const win=window.open('','_blank');if(!win)return showMessage('اسمح بالنوافذ المنبثقة لطباعة التقرير.');
   win.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>تقرير ${esc(t.name)}</title><style>body{font-family:Arial,sans-serif;padding:24px;color:#111}h1,h2,h3,h4{margin:18px 0 8px}table{width:100%;border-collapse:collapse;margin:10px 0 22px}th,td{border:1px solid #aaa;padding:7px;text-align:right;font-size:12px;vertical-align:top}.trainee-report-header{text-align:center;border-bottom:2px solid #333;padding-bottom:12px}.panel{border:1px solid #ccc;padding:10px;margin:10px 0;break-inside:avoid}.meta{display:flex;gap:12px;flex-wrap:wrap;font-size:12px}.trainee-video-question{border-top:1px solid #ddd;padding:5px 0}p{line-height:1.6}button{display:none}@media print{body{padding:8mm}h3{break-after:avoid}}</style></head><body>${$('#traineeReportPrint').innerHTML}<script>window.onload=()=>window.print()<\/script></body></html>`);
   win.document.close();
  };
 }catch(error){const target=$('#traineePerformanceBody');if(target)target.innerHTML=`<p class="error">تعذر تحميل التقرير: ${esc(error.message)}</p>`}
}



// Interactive library video controls (merged from British library module).
document.addEventListener("click",e=>{
 const watch=e.target.closest("[data-watch-video]");
 if(watch){openLibraryVideo(Number(watch.dataset.watchVideo));return;}
 const analytics=e.target.closest("[data-video-analytics]");
 if(analytics){loadVideoAnalytics(Number(analytics.dataset.videoAnalytics));return;}
 const share=e.target.closest("[data-share-video]");
 if(share){const url=`${location.origin}/#library-video-${share.dataset.shareVideo}`;if(navigator.share)navigator.share({title:share.dataset.title||"فيديو تدريبي",url}).catch(()=>{});else navigator.clipboard?.writeText(url).then(()=>showMessage("تم نسخ رابط المشاركة.")).catch(()=>showMessage("تعذر نسخ الرابط."));return;}
 const like=e.target.closest("[data-video-like]");
 if(like){api(`/library/${like.dataset.videoLike}/reaction`,{method:"POST"}).then(d=>{like.innerHTML=`${d.liked?"♥":"♡"} إعجاب · <span id="videoLikeCount">${d.count}</span>`}).catch(err=>showMessage(err.message));return;}
 const answer=e.target.closest("[data-video-answer]");
 if(answer){
  const choices=[...answer.closest(".video-answer-list").querySelectorAll("[data-video-answer]")];
  choices.forEach(b=>b.disabled=true);
  api(`/library/${answer.dataset.videoId}/answer`,{method:"POST",body:JSON.stringify({question_id:Number(answer.dataset.questionId),selected_index:Number(answer.dataset.videoAnswer)})}).then(d=>{
   const feedback=document.querySelector("#videoAnswerFeedback");
   if(feedback){feedback.textContent=d.message;feedback.className=d.correct?"video-answer-feedback is-correct":"video-answer-feedback is-wrong";}
   const box=answer.closest(".video-question-shade");box?.remove();
   const player=document.querySelector("#libraryVideoPlayer");
   if(player){player.play().catch(()=>{});}
   const qid=Number(answer.dataset.questionId);
   if(d.correct)window.__libraryAnsweredQuestionIds?.add(qid);
   else choices.forEach(b=>b.disabled=false);
  }).catch(err=>{const feedback=document.querySelector("#videoAnswerFeedback");if(feedback)feedback.textContent=err.message;choices.forEach(b=>b.disabled=false);});
 }
});
